#define MAX_N 200005

typedef struct Edge {
    int to;
    int next;
} Edge;

Edge edges[MAX_N * 2];
int head[MAX_N];
int edge_cnt;

int a[MAX_N];
int dp[MAX_N];      // dp[i] = LIS ending at vertex i (considering path from root)
int ans[MAX_N];     // answer for each vertex
int lis_len;        // current length of LIS array
int lis[MAX_N];     // classical LIS array (strictly increasing)

void add_edge(int u, int v) {
    edges[edge_cnt].to = v;
    edges[edge_cnt].next = head[u];
    head[u] = edge_cnt++;
}

// Binary search for strictly increasing LIS
int find_pos(int val) {
    int lo = 0, hi = lis_len - 1;
    while (lo <= hi) {
        int mid = (lo + hi) / 2;
        if (lis[mid] < val) {
            lo = mid + 1;
        } else {
            hi = mid - 1;
        }
    }
    return lo; // first index where lis[idx] >= val
}

void dfs(int u, int parent) {
    // Compute LIS for current path
    int pos = find_pos(a[u]);
    int old_val = lis[pos];
    int old_len = lis_len;

    lis[pos] = a[u];
    if (pos == lis_len) {
        lis_len++;
    }

    ans[u] = lis_len; // LIS length for path from 1 to u

    for (int i = head[u]; i != -1; i = edges[i].next) {
        int v = edges[i].to;
        if (v == parent) continue;
        dfs(v, u);
    }

    // Backtrack
    lis[pos] = old_val;
    if (pos == old_len) {
        lis_len = old_len;
    }
}

