#define MAXN 200005

int a[MAXN];
int ans[MAXN];
int head[MAXN], nxt[2*MAXN], to[2*MAXN], ecnt;
int tails[MAXN], tlen;
int n;

void add_edge(int u, int v) {
    ecnt++;
    to[ecnt] = v;
    nxt[ecnt] = head[u];
    head[u] = ecnt;
}

// lower_bound: first index in tails[0..tlen-1] where tails[idx] >= x
int lower_bound(int x) {
    int lo = 0, hi = tlen;
    while (lo < hi) {
        int mid = (lo + hi) / 2;
        if (tails[mid] < x) lo = mid + 1;
        else hi = mid;
    }
    return lo;
}

void dfs(int u, int parent) {
    int x = a[u];
    int pos = lower_bound(x);
    int old_val;
    int extended = 0;
    if (pos == tlen) {
        tails[tlen] = x;
        tlen++;
        extended = 1;
        old_val = 0; // doesn't matter
    } else {
        old_val = tails[pos];
        tails[pos] = x;
    }

    ans[u] = tlen;

    for (int e = head[u]; e; e = nxt[e]) {
        int v = to[e];
        if (v != parent) {
            dfs(v, u);
        }
    }

    // backtrack
    if (extended) {
        tlen--;
    } else {
        tails[pos] = old_val;
    }
}

