static int lower_bound_int(int *arr, int len, int x) {
    int l = 0, r = len;
    while (l < r) {
        int m = (l + r) >> 1;
        if (arr[m] >= x) r = m;
        else l = m + 1;
    }
    return l;
}

int main(void) {
    int N;
    if (scanf("%d", &N) != 1) return 0;

    int *a = (int *)malloc((N + 1) * sizeof(int));
    for (int i = 1; i <= N; i++) scanf("%d", &a[i]);

    Edge *edges = (Edge *)malloc((2 * (N - 1)) * sizeof(Edge));
    int *head = (int *)malloc((N + 1) * sizeof(int));
    for (int i = 1; i <= N; i++) head[i] = -1;

    int ecnt = 0;
    for (int i = 0; i < N - 1; i++) {
        int u, v;
        scanf("%d %d", &u, &v);
        edges[ecnt].to = v;
        edges[ecnt].next = head[u];
        head[u] = ecnt++;

        edges[ecnt].to = u;
        edges[ecnt].next = head[v];
        head[v] = ecnt++;
    }

    int *ans = (int *)malloc((N + 1) * sizeof(int));
    int *lis = (int *)malloc((N + 1) * sizeof(int));

    int *stack_v = (int *)malloc((2 * N + 5) * sizeof(int));
    int *stack_p = (int *)malloc((2 * N + 5) * sizeof(int));
    int *stack_state = (int *)malloc((2 * N + 5) * sizeof(int)); // 0=enter, 1=exit
    int *stack_pos = (int *)malloc((2 * N + 5) * sizeof(int));
    int *stack_old = (int *)malloc((2 * N + 5) * sizeof(int));

    int top = 0;
    int lis_len = 0;

    stack_v[top] = 1;
    stack_p[top] = 0;
    stack_state[top] = 0;
    stack_pos[top] = -1;
    stack_old[top] = 0;
    top++;

    while (top > 0) {
        top--;
        int v = stack_v[top];
        int p = stack_p[top];
        int state = stack_state[top];
        int pos = stack_pos[top];
        int old = stack_old[top];

        if (state == 0) {
            int idx = lower_bound_int(lis, lis_len, a[v]);
            int prev = 0;
            int extended = 0;
            if (idx == lis_len) {
                lis[lis_len++] = a[v];
                extended = 1;
            } else {
                prev = lis[idx];
                lis[idx] = a[v];
            }
            ans[v] = lis_len;

            stack_v[top] = v;
            stack_p[top] = p;
            stack_state[top] = 1;
            stack_pos[top] = idx;
            stack_old[top] = extended ? 0 : prev;
            top++;

            for (int e = head[v]; e != -1; e = edges[e].next) {
                int to = edges[e].to;
                if (to == p) continue;
                stack_v[top] = to;
                stack_p[top] = v;
                stack_state[top] = 0;
                stack_pos[top] = -1;
                stack_old[top] = 0;
                top++;
            }
        } else {
            if (pos == lis_len - 1 && lis[pos] == a[v]) {
                lis_len--;
            } else {
                lis[pos] = old;
            }
        }
    }

    for (int i = 1; i <= N; i++) {
        printf("%d\n", ans[i]);
    }

    free(a);
    free(edges);
    free(head);
    free(ans);
    free(lis);
    free(stack_v);
    free(stack_p);
    free(stack_state);
    free(stack_pos);
    free(stack_old);

    return 0;
}

