        for (int i = 1; i <= n; i++) {
            sb.append(ans[i]).append("\n");
        }
        System.out.print(sb);
    }

    static void dfs(int u, int parent) {
        int pos = binarySearch(lis, 0, lisLen - 1, a[u]);
        int replaced = -1;
        if (pos == lisLen) {
            lis[lisLen++] = a[u];
        } else {
            replaced = lis[pos];
            lis[pos] = a[u];
        }
        ans[u] = lisLen;

        for (int v : adj[u]) {
            if (v != parent) {
                dfs(v, u);
            }
        }

        // backtrack
        if (replaced == -1) {
            lisLen--;
        } else {
            lis[pos] = replaced;
        }
    }

    static int binarySearch(int[] arr, int l, int r, int key) {
        while (l <= r) {
            int mid = (l + r) / 2;
            if (arr[mid] < key) {
                l = mid + 1;
            } else {
                r = mid - 1;
            }
        }
        return l;
    }
}

import java.util.*;
