public class Main {
    static int[] a;
    static List<Integer>[] adj;
    static int[] ans;
    static int[] tails; // tails array for LIS
    static int lisLen;

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        int N = Integer.parseInt(br.readLine().trim());
        a = new int[N + 1];
        StringTokenizer st = new StringTokenizer(br.readLine());
        for (int i = 1; i <= N; i++) a[i] = Integer.parseInt(st.nextToken());

        adj = new List[N + 1];
        for (int i = 1; i <= N; i++) adj[i] = new ArrayList<>();
        for (int i = 0; i < N - 1; i++) {
            st = new StringTokenizer(br.readLine());
            int u = Integer.parseInt(st.nextToken());
            int v = Integer.parseInt(st.nextToken());
            adj[u].add(v);
            adj[v].add(u);
        }

        ans = new int[N + 1];
        tails = new int[N + 1];
        lisLen = 0;

        // DFS iteratively with undo
        // Use explicit stack: (vertex, parent, phase, pos, oldVal)
        // phase 0: entering, phase 1: leaving
        Deque<int[]> stack = new ArrayDeque<>();
        // {vertex, parent, phase, pos, oldVal}
        stack.push(new int[]{1, -1, 0, -1, -1});

        while (!stack.isEmpty()) {
            int[] frame = stack.peek();
            int v = frame[0], par = frame[1], phase = frame[2];

            if (phase == 0) {
                frame[2] = 1; // mark as leaving next time
                // Add a[v] to tails
                int val = a[v];
                int pos = lowerBound(tails, lisLen, val);
                int oldVal = (pos < lisLen) ? tails[pos] : Integer.MAX_VALUE;
                frame[3] = pos;
                frame[4] = oldVal;
                tails[pos] = val;
                if (pos == lisLen) lisLen++;
                ans[v] = lisLen;

                // Push children
                for (int child : adj[v]) {
                    if (child != par) {
                        stack.push(new int[]{child, v, 0, -1, -1});
                    }
                }
            } else {
                stack.pop();
                // Undo: restore tails
                int pos = frame[3];
                int oldVal = frame[4];
                if (oldVal == Integer.MAX_VALUE) {
                    lisLen--;
                } else {
                    tails[pos] = oldVal;
                }
            }
        }

        StringBuilder sb = new StringBuilder();
        for (int i = 1; i <= N; i++) {
            sb.append(ans[i]).append('\n');
        }
        System.out.print(sb);
    }

    static int lowerBound(int[] arr, int len, int val) {
        int lo = 0, hi = len;
        while (lo < hi) {
            int mid = (lo + hi) / 2;
            if (arr[mid] < val) lo = mid + 1;
            else hi = mid;
        }
        return lo;
    }
}

import java.io.*;
import java.util.*;

public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            int val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }

    static int N;
    static int[] a;
    static ArrayList<Integer>[] g;
    static int[] ans;
    static ArrayList<Integer> lis = new ArrayList<>();

    static void dfs(int v, int p) {
        int x = a[v];
        int pos = lowerBound(lis, x);
        boolean appended = false;
        int oldValue = -1;

        if (pos == lis.size()) {
            lis.add(x);
            appended = true;
        } else {
            oldValue = lis.get(pos);
            lis.set(pos, x);
        }

        ans[v] = lis.size();

        for (int to : g[v]) {
            if (to == p) continue;
            dfs(to, v);
        }

        if (appended) {
            lis.remove(lis.size() - 1);
        } else {
            lis.set(pos, oldValue);
        }
    }

    static int lowerBound(ArrayList<Integer> list, int x) {
        int l = 0, r = list.size();
        while (l < r) {
            int m = (l + r) >>> 1;
            if (list.get(m) >= x) r = m;
            else l = m + 1;
        }
        return l;
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();
        N = fs.nextInt();

        a = new int[N + 1];
        for (int i = 1; i <= N; i++) a[i] = fs.nextInt();

        g = new ArrayList[N + 1];
        for (int i = 1; i <= N; i++) g[i] = new ArrayList<>();

        for (int i = 0; i < N - 1; i++) {
            int u = fs.nextInt();
            int v = fs.nextInt();
            g[u].add(v);
            g[v].add(u);
        }

        ans = new int[N + 1];
        dfs(1, 0);

        StringBuilder sb = new StringBuilder();
        for (int i = 1; i <= N; i++) {
            sb.append(ans[i]).append('\n');
        }
        System.out.print(sb.toString());
    }
